import numpy as np, scipy.linalg as la, json, time, sys
from pathlib import Path
sys.path.insert(0,'experiments/e1')
from agent4_interval_model import blocks as hpblocks

def mul(p,f):
 p=np.convolve(p,f);p/=np.max(np.abs(p));return p

def parameters(r,d,hs):
 hs=np.array(hs,dtype=np.longdouble)
 def z(h,r):return np.where(h<=0,r/(np.hypot(h,r)-h),(np.hypot(h,r)+h)/r)
 return z(hs,r),z(hs-d,1)

def blocksigns(m,r,d,hs):
 x,y=parameters(r,d,hs); k=len(x);n=k+2*m
 H=np.ones(1,dtype=np.longdouble)
 for j in range(1,m):H=np.r_[H,H[-1]/np.tan(np.longdouble(j)*np.pi/(2*m))]
 H/=max(H)
 A=np.ones(1,dtype=np.clongdouble);B=A.copy()
 for j in range(m):
  zz=np.exp(np.clongdouble(2j*np.pi*j/m))
  D=d+np.hypot(d,abs(zz-r)); cc=(zz.conjugate()-r)/D;bb=(1-r*zz)/D
  A=mul(A,[1,-cc]); B=mul(B,[bb,1])
 A=mul(A,H);B=mul(B,H)
 for u,v in zip(x,y):A=mul(A,[u,1]);B=mul(B,[v,1])
 out=[]
 for q in range(m):
  cols=list(range(q,n,m));ix=list(range(q,k,m));Q=np.zeros((len(cols),len(cols)))
  for j,i in enumerate(ix):
   u=x[i]**m;v=y[i]**m; row=np.array([1,-u-v,u*v],dtype=np.longdouble);row/=max(abs(row));Q[j,j:j+3]=row
  Q[-2]=A[cols].real;Q[-1]=B[cols].real
  Q[-2]/=max(abs(Q[-2]));Q[-1]/=max(abs(Q[-1]));
  out.append(la.det(Q,check_finite=False))
 return out,x,y

if __name__=='__main__':
 rng=np.random.default_rng(763532);start=time.time();bad=0
 for t in range(5000):
  m=int(rng.integers(1,33));a=int(rng.integers(1,65));b=int(rng.integers(1,65));
  r=np.exp(rng.uniform(-7,-.0001));d=np.exp(rng.uniform(-8,6))
  hs=np.r_[-np.sort(np.exp(rng.uniform(-10,10,a)))[::-1],d+np.sort(np.exp(rng.uniform(-10,10,b)))]
  vals,x,y=blocksigns(m,r,d,hs)
  if min(vals)<=0:
   bad+=1;q=int(np.argmin(vals));print('candidate',t,m,a,b,r,d,q,min(vals),flush=True)
   checks=hpblocks(m,r,d,x,y,150)
   if min(checks)<0:
    data=dict(m=m,a=a,b=b,r=r,d=d,hs=hs.tolist(),vals=list(map(str,checks)))
    Path('candidate.json').write_text(json.dumps(data));print('HIGH PRECISION NEGATIVE',data,flush=True);break
  if t%200==0:print('progress',t,'bad',bad,'elapsed',time.time()-start,flush=True)

